/*
asin from trigonometry
b = asin²(a)
where
a: scalar
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT b;

    heartlib(const double & a)
    {

        // b = asin²(a)
        b = pow(asin(a), 2);
    }
};

